CREATE OR REPLACE FUNCTION compute_rrs(recscore numeric, confval numeric, recutil numeric)
RETURNS numeric AS $$
BEGIN
    RETURN (recscore + confval + recutil) / 3;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs(recscore numeric, confval numeric, recutil numeric)
RETURNS numeric AS $$
BEGIN
    RETURN (recscore + confval + recutil) / 3;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs(recscore numeric, confval numeric, recutil numeric)
RETURNS numeric AS $$
BEGIN
    RETURN ROUND((recscore + confval + recutil) / 3, 2);
END;
$$ LANGUAGE plpgsql;
